template <typename T>
class ObjectCounter {
public:
    static int instances; // Declaration
    ObjectCounter() { instances++; }
};

// Definition template (must match class template)
template <typename T>
int ObjectCounter<T>::instances = 0;

// Implicit Instantiation occurs upon use:

// Instantiates ObjectCounter<int>::instances (set to 0)
ObjectCounter<int> i1;
ObjectCounter<int> i2; // i::instances == 2

// Instantiates ObjectCounter<float>::instances (set to 0)
ObjectCounter<float> f1; // f::instances == 1
